import fs from 'node:fs';
import os from 'node:os';
import {performance} from 'node:perf_hooks';
const groups = [
 ['先给出结论，再解释原因。','开头点明观点，随后展开依据。','不要先给出结论，应先解释原因。','只有技术教程适合先给出结论，再解释原因。','每篇文章至少引用三个独立来源。'],
 ['技术教程应给出可复现的操作步骤。','写技术教程时，要让读者能够按步骤重复操作。','技术教程不应给出可复现的操作步骤。','情绪随笔应给出可复现的操作步骤。','图片应该保留清晰的文字。'],
 ['缺乏证据时，不要把相关性写成因果关系。','没有充分依据，就不能声称两个现象存在因果联系。','缺乏证据时，可以把相关性写成因果关系。','只有讨论医疗问题时，才不能把相关性写成因果关系。','评论开头可以直接回应具体细节。'],
 ['针对新手的教程需要解释专业术语。','面向初学者写教程时，应说明技术名词的含义。','针对新手的教程不需要解释专业术语。','针对专家的教程需要解释专业术语。','视频封面不应遮挡关键画面。'],
 ['引用数据时，应标明来源和统计时间。','使用数字论据，要交代数据出处及对应的时间范围。','引用数据时，不必标明来源和统计时间。','只有引用自己的数据时，才应标明来源和统计时间。','每段文字尽量表达一个核心观点。'],
 ['样本不足时，应明确说明结论的局限。','观察数量太少时，需要交代判断的适用限制。','样本不足时，不应说明结论的局限。','只有样本充足时，才应明确说明结论的局限。','产品截图需要清楚显示操作入口。'],
 ['回复问题时，应先回应对方的具体疑问。','回答别人时，优先解答他实际提出的问题。','回复问题时，应避免回应对方的具体疑问。','只有回复付费用户时，才应先回应对方的具体疑问。','引用他人观点应注明作者。'],
 ['低曝光不能直接证明帖子内容质量差。','不能只因为浏览量少，就认定一条帖子没有内容价值。','低曝光能直接证明帖子内容质量差。','低曝光不能直接证明技术帖内容质量差。','标题需要准确反映正文。'],
 ['讲解排障经验时，先描述现象，再说明解决步骤。','分享故障处理方法，应先交代问题表现，再给出处理流程。','讲解排障经验时，不要先描述现象，应直接说明解决步骤。','撰写产品广告时，先描述现象，再说明解决步骤。','转载图片要尊重作者许可。'],
 ['在结尾提出问题时，应与正文主题相关。','文章末尾的问题要围绕前文讨论的内容。','在结尾提出问题时，不应与正文主题相关。','只有长篇文章结尾的问题才需要与正文主题相关。','删除帖子之前应检查其来源。'],
];
const pairs=[];
for(let i=0;i<groups.length;i++) for(let j=1;j<5;j++)pairs.push({id:`g${i+1}-${j}`,category:['','paraphrase','negation','scope','unrelated'][j],same:j===1,a:groups[i][0],b:groups[i][j]});
pairs.push(...[
 ['发布前至少检查两遍正文。','发布前至少检查三遍正文。'],
 ['只分析最近七天的帖子。','只分析最近三十天的帖子。'],
 ['每批最多分析二十条帖子。','每批至少分析二十条帖子。'],
 ['曝光低于一百时再复查。','曝光高于一百时再复查。'],
].map(([a,b],i)=>({id:`number-${i}`,category:'quantity',same:false,a,b})));
fs.writeFileSync('corpus.json',JSON.stringify(pairs,null,2));
const stages=[]; let peak=0;
function snap(name){const m=process.memoryUsage();peak=Math.max(peak,m.rss);const x={name,ms:performance.now(),...m};stages.push(x);console.log(JSON.stringify(x));}
snap('before_import');
const {pipeline,env}=await import('@huggingface/transformers');
env.cacheDir='./model-cache';
snap('after_import');
const t=performance.now();
const extractor=await pipeline('feature-extraction','Xenova/paraphrase-multilingual-MiniLM-L12-v2',{dtype:'q8',device:'cpu',progress_callback:p=>{if(p.status==='done')console.log('downloaded '+p.file);}});
snap('loaded');
const loadMs=performance.now()-t;
const texts=[...new Set(pairs.flatMap(p=>[p.a,p.b]))];const vectors=new Map();const timings=[];
for (const s of texts){const st=performance.now();const result=await extractor(s,{pooling:'mean',normalize:true});timings.push(performance.now()-st);vectors.set(s,Array.from(result.data));peak=Math.max(peak,process.memoryUsage().rss);}
snap('after_inference');
const scored=pairs.map(p=>({...p,score:vectors.get(p.a).reduce((sum,v,i)=>sum+v*vectors.get(p.b)[i],0)}));
const thresholds=[0.7,0.75,0.8,0.85,0.9,0.95].map(threshold=>({threshold,tp:scored.filter(p=>p.same&&p.score>=threshold).length,fp:scored.filter(p=>!p.same&&p.score>=threshold).length,byCategory:Object.fromEntries(['negation','scope','quantity','unrelated'].map(c=>[c,scored.filter(p=>p.category===c&&p.score>=threshold).length]))}));
const summary=Object.fromEntries([...new Set(scored.map(p=>p.category))].map(c=>{let v=scored.filter(p=>p.category===c).map(p=>p.score);return [c,{n:v.length,min:Math.min(...v),max:Math.max(...v),mean:v.reduce((a,b)=>a+b)/v.length}]}));
await extractor.dispose();snap('disposed');
const out={date:new Date().toISOString(),node:process.version,os:os.version(),cpu:os.cpus()[0].model,logicalCpus:os.cpus().length,ram:os.totalmem(),model:'Xenova/paraphrase-multilingual-MiniLM-L12-v2',dtype:'q8',device:'cpu',loadMs,uniqueTexts:texts.length,firstInferenceMs:timings[0],meanInferenceMs:timings.reduce((a,b)=>a+b)/timings.length,stages,peakSampledRss:peak,peakOsRssKiB:process.resourceUsage().maxRSS,summary,thresholds,pairs:scored};
fs.writeFileSync(process.env.RESULT_FILE||'results.json',JSON.stringify(out,null,2));console.log(JSON.stringify({loadMs,summary,thresholds,peakSampledRss:peak}));
